];
const schema = JSON.stringify({type:'object',properties:{chapter:{type:'integer'},title:{type:'string'},path:{type:'string'},summary:{type:'string'},char_count:{type:'integer'},sources:{type:'array',items:{type:'string'}},status:{type:'string'}},required:['chapter','title','path','summary','char_count','sources','status']});
const results = await parallel('十二章独立研究与写作', () => chapters.map(c => agent(
  `你是工程建设与风险管理研究专家。请独立完成第${c.n}章《${c.title}》。研究重点：${c.focus}\n\n硬性要求：\n1. 使用简体中文写作，章节正文不少于4500个中文字符，至少包含6个一级以下小节、至少2个Markdown表格；每个正文段落不少于150个汉字，避免碎片化短句。\n2. 事实、法规、统计数据和案例必须来自可公开访问且可靠的来源，优先中国政府部门、全国人大/国务院、国家标准公开信息、水利部、生态环境部、应急管理部、国家统计局、中国气象局、地震局、最高人民法院、国际组织和项目业主/官方报告；至少使用8个来源，关键事实尽量多渠道交叉验证。\n3. 在正文相关句子后使用编号引用[1]、[2]，章节末尾给出“## 本章参考资料”并按“[1]: URL \\"标题\\"”列出可访问网址；不得编造网址、数据、案例或标准编号。无法核实的资料不要写入。\n4. 报告需要解释分析逻辑、风险因果链、管理机制、适用边界与判断依据，但不要披露模型隐藏思维过程；以可审计的论证、假设、公式、评价矩阵和证据说明替代。\n5. 与其他章节尽量错开：只围绕本章主题展开，必要的跨章内容仅作接口说明，不重复长篇定义。不得出现“待补充”“TODO”“占位”等字样。\n6. 将完整章节写入绝对路径 /home/ubuntu/epc_report/chapters/${String(c.n).padStart(2,'0')}.md，文件第一行使用“# 第${c.n}章 ${c.title}”。完成后返回结构化结果。`,
  {brief:`撰写第${c.n}章：${c.title}`,sandbox:'shared',effort_level:'standard',schema}
)), {schema});
return results.map(r => r.ok ? r.value : {chapter:0,title:'失败项',path:'',summary:r.error.message,char_count:0,sources:[],status:'failed'});

